static void scopes_clear(struct em_scopes *members)
{
	struct neocc_scope_frame *lists[] = { members->active,
					     members->available };

	for (size_t i = 0; i < sizeof(lists) / sizeof(lists[0]); i++) {
		struct neocc_scope_frame *frame = lists[i];

		while (frame) {
			struct neocc_scope_frame *next = frame->next;

			free(frame);
			frame = next;
		}
	}
	*members = (struct em_scopes){ 0 };
}

static int scopes_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int scopes_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_scopes *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		scopes_clear(members);
	return R_P;
}

static int scopes_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_scopes *members = self->members;

	if (action != NEOCC_AC0_SCOPES_RESET) {
		SBO_OBJECT_INTERACT0;
	}

	if (!self->ref_count)
		return RN_INVALIDARG;
	scopes_clear(members);
	return R_P;
}

