static int scopes_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_scopes *members = self->members;
	struct neocc_scopes *state = &members->state;

	*output_quantity = 0;
	if (action != NEOCC_AC1_SCOPES_BORROW &&
	    action != NEOCC_AC1_SCOPES_ENTER) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count)
		return RN_INVALIDARG;
	if (action == NEOCC_AC1_SCOPES_ENTER) {
		struct neocc_scope_frame *frame;
		struct neocc_scope *scope;

		if (capacity < sizeof(scope))
			return RN_INVALIDARG;
		frame = members->available;
		if (frame)
			members->available = frame->next;
		else
			frame = malloc(sizeof(*frame));
		if (!frame)
			return R_N;
		scope = &frame->scope;
		*scope = state->current ? *state->current :
			(struct neocc_scope){ 0 };
		scope->prev = state->current;
		scope->vla.num = 0;
		frame->next = members->active;
		members->active = frame;
		state->current = scope;
		if (!state->root)
			state->root = scope;
		memcpy(output_stream, &scope, sizeof(scope));
		*output_quantity = sizeof(scope);
		return R_P;
	}
	if (capacity < sizeof(state))
		return RN_INVALIDARG;
	memcpy(output_stream, &state, sizeof(state));
	*output_quantity = sizeof(state);
	return R_P;
}

static int scopes_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_scopes *members = self->members;
	struct neocc_scope_frame *frame = members->active;
	struct neocc_scope *scope;

	if (action != NEOCC_AC2_SCOPES_EXIT) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || quantity != sizeof(scope))
		return RN_INVALIDARG;
	memcpy(&scope, input_stream, sizeof(scope));
	if (!frame || scope != &frame->scope ||
	    members->state.loop == scope)
		return RN_INVALIDARG;
	members->state.current = scope->prev;
	if (members->state.root == scope)
		members->state.root = NULL;
	members->active = frame->next;
	frame->scope = (struct neocc_scope){ 0 };
	frame->next = members->available;
	members->available = frame;
	return R_P;
}

void tog_scopes(struct object *object)
{
	object->open = scopes_open;
	object->input = scopes_input;
	object->output = scopes_output;
	object->io_put = scopes_io_put;
	object->interact0 = scopes_interact0;
	object->interact1 = scopes_interact1;
	object->interact2 = scopes_interact2;
	object->interact3 = scopes_interact3;
	object->close = scopes_close;
}
